import{_ as t,o as n,c as r,ag as s}from"./chunks/framework.D5hoimZQ.js";const l=JSON.parse('{"title":"🔬 科学日报 | 2026年10月13日 · 深度扩展","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/science-daily/2026-10-13.md","filePath":"science-log/src/science-daily/2026-10-13.md"}'),e={name:"science-log/src/science-daily/2026-10-13.md"};function g(a,o,c,i,d,p){return n(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="🔬-科学日报-2026年10月13日-·-深度扩展" tabindex="-1">🔬 科学日报 | 2026年10月13日 · 深度扩展 <a class="header-anchor" href="#🔬-科学日报-2026年10月13日-·-深度扩展" aria-label="Permalink to &quot;🔬 科学日报 | 2026年10月13日 · 深度扩展&quot;">​</a></h1><blockquote><p>来源：当天简讯（科学快报 第36期 · 原版，共 10 条：🔬 科学前沿 5 篇 + 🤖 AI 前沿 5 篇） 分析日期：2026-10-13 版本：扩展版（10 条深度 + 机制层 + 第一性原理层 + 交叉关联）</p></blockquote><blockquote><p>⚠️ 说明：本日简讯为<strong>当日原版</strong>（<code>/tmp/ScienceDaily/daily/2026-10-13.md</code>，第36期），非事后重建。10 条论文均已于 2026-11-05 经 CrossRef（Nature 0028-0836 系）与 arXiv API（id_list）逐条核对<strong>标题、期刊、作者、DOI</strong> 属实；下述深度扩展的机制细节照简讯原文解读，未擅自增补未核实的数字。</p></blockquote><hr><h2 id="🔬-一、科学前沿" tabindex="-1">🔬 一、科学前沿 <a class="header-anchor" href="#🔬-一、科学前沿" aria-label="Permalink to &quot;🔬 一、科学前沿&quot;">​</a></h2><h3 id="_1-细菌也会用-端粒酶式-逆转录来抗病毒" tabindex="-1">1. 细菌也会用&quot;端粒酶式&quot;逆转录来抗病毒 <a class="header-anchor" href="#_1-细菌也会用-端粒酶式-逆转录来抗病毒" aria-label="Permalink to &quot;1. 细菌也会用&quot;端粒酶式&quot;逆转录来抗病毒&quot;">​</a></h3><p><strong>原文</strong>：研究识别出一个新的抗病毒防御系统 DRT10（防御相关逆转录酶家族的一员），它结合一段非编码 RNA，以&quot;蛋白引物&quot;方式持续合成串联重复 DNA。逆转录由 ncRNA 上一段特定区域作模板，带明确序列模式与模板边界元件；冷冻电镜显示罕见的 2:1 结构——两个 RT 单体分别结合在一条拟对称 ncRNA 的两侧，各自逆转录自己一侧的模板，但只有一侧产生长重复产物，其模板长度由两个侧翼发夹锚点之间的间距决定。这种&quot;迭代、边界受限&quot;的 cDNA 合成机制与真核端粒酶的端粒重复加尾高度相似；跨生命域的系统发生分析把端粒酶与 DRT 家族放进同一单系演化支，提示二者有共同起源。</p><p><strong>深度扩展</strong>：</p><p>发表于《Nature》（2026），作者 <strong>Stephen Tang、Josephine L. Ramirez、Qixiang He、Mario Rodríguez Mestre、Tanner Wiegand</strong> 等（DOI: 10.1038/s41586-026-11250-8，CrossRef 载入库日 2026-10-12）。这项工作把细菌的&quot;免疫记忆&quot;研究推进到分子结构层次。</p><p><strong>背景</strong>：细菌抵御噬菌体的手段之一是一类&quot;防御相关逆转录酶&quot;（DRT）系统——它们以 RNA 为模板合成 DNA（cDNA），借此干扰噬菌体复制。DRT 家族成员众多，但绝大多数成员<strong>究竟如何工作</strong>长期是黑箱。</p><p><strong>方法</strong>：团队从该家族中鉴别出 <strong>DRT10</strong>，用生化和冷冻电镜结构解析其活性构象。DRT10 结合一段<strong>非编码 RNA（ncRNA）</strong>，以<strong>蛋白引物（protein-primed）<strong>方式</strong>持续性</strong>合成<strong>串联重复 DNA</strong>，模板是 ncRNA 上一段带<strong>特征序列模式</strong>与<strong>模板边界元件</strong>的区域——两者都保守、都对重复添加必需。</p><p><strong>关键结构</strong>：冷冻电镜显示罕见的 <strong>2:1 化学计量</strong>——两个 RT 单体分别结合在一条<strong>拟对称 ncRNA</strong> 的两侧；每个单体各自逆转录自己那一侧的模板，但<strong>只有一侧产生长重复产物</strong>，其长度由<strong>两个侧翼发夹锚点之间的间距</strong>决定。这是一种&quot;<strong>迭代、边界受限</strong>&quot;的 cDNA 合成。</p><p><strong>为什么重要</strong>：该机制与真核<strong>端粒酶加端粒重复</strong>在逻辑上高度平行（模板区、边界锚定、迭代加尾），且<strong>跨生命域的 RT 系统发生分析把端粒酶与 DRT 家族归入同一单系支</strong>——提示细菌抗病毒免疫与真核染色体维护<strong>共用同一套逆转录工具箱</strong>，是&quot;进化复用&quot;的经典范例。</p><p><strong>跨主题关联</strong>：与 <code>topics/biomedicine/science-daily-2026-10-13.md</code> 同题；机制主线&quot;边界决定重复单元长度&quot;呼应 <code>topics/biomedicine/chloroplast-endosymbiosis.md</code>（内共生与跨域基因共享）的演化复用母题。</p><hr><h3 id="_2-首次在人脑中量化-lsd-的受体占据与血流效应" tabindex="-1">2. 首次在人脑中量化 LSD 的受体占据与血流效应 <a class="header-anchor" href="#_2-首次在人脑中量化-lsd-的受体占据与血流效应" aria-label="Permalink to &quot;2. 首次在人脑中量化 LSD 的受体占据与血流效应&quot;">​</a></h3><p><strong>原文</strong>：作者用同步 PET–MRI，在 7 名对剂量设盲的健康志愿者身上同时测量 LSD 的分子与血流动力学作用。结果显示：LSD 以高亲和力占据 5-HT2A 受体，升高全局脑血流与颈内动脉血流；同时降低全局功能连接，且连接下降与血流升高呈负相关。血浆药物浓度与主观体验之间出现逆时针滞后环，提示非典型的药效动力学机制。研究另以 25 名服用裸盖菇素（psilocybin）的受试者作对照，凸显 LSD 与裸盖菇素的神经生理差异；首次在人体建立 LSD 的剂量—受体占据关系，为迷幻药物的临床开发提供依据。</p><p><strong>深度扩展</strong>：</p><p>发表于《Nature Neuroscience》（2026），第一作者 <strong>Drummond E-Wen McCulloch</strong>（与 Kristian Larsen、Annette Johansen 等，DOI: 10.1038/s41593-026-02462-2）。这是把&quot;迷幻药分子靶点&quot;与&quot;全脑系统响应&quot;第一次<strong>在同一批人体上、同一时刻</strong>同时量化的研究。</p><p><strong>方法</strong>：用<strong>同步 PET–MRI</strong>，对 <strong>7 名对剂量设盲</strong>的健康志愿者，一边用 PET 测 <strong>5-HT2A 受体的占据率</strong>（靶点结合，target engagement），一边用 MRI 测<strong>全局脑血流（CBF）<strong>与</strong>功能连接</strong>。</p><p><strong>关键结果</strong>：（1）LSD <strong>高亲和力占据 5-HT2A</strong>；（2）<strong>升高全局脑血流与颈内动脉血流</strong>；（3）<strong>降低全局功能连接</strong>，且<strong>连接下降与血流升高呈负相关</strong>；（4）血浆药物浓度与主观体验之间出现<strong>逆时针滞后环</strong>——效应不简单跟随血药浓度，提示<strong>非典型药效动力学</strong>（可能涉及下游信号放大与受体后级联的时间常数）。</p><p><strong>对照与意义</strong>：另以 <strong>25 名服用裸盖菇素（psilocybin）<strong>的受试者作对照，凸显两者虽</strong>同打 5-HT2A</strong>，却在血流/连接等系统级指标上可分。首次在人体建立 <strong>LSD 的剂量—受体占据关系</strong>，为迷幻药物的临床剂量选择提供<strong>靶点结合</strong>的定量锚点。</p><p><strong>跨主题关联</strong>：与 <code>topics/neuroscience/science-daily-2026-10-13.md</code> 同题；&quot;占据同一受体 ≠ 相同脑效应&quot;的系统药理学母题，可对话 <code>topics/psychology/index.md</code>（意识/体验的神经底物）与 <code>topics/neuroscience/index.md</code>（脑网络与功能连接）。</p><hr>',24)])])}const q=t(e,[["render",g]]);export{l as __pageData,q as default};
